<!DOCTYPE html>
<html lang="en">
<head><meta charset="utf-8"><title>{{ $certificate->certificate_number }}</title><style>
    @page { margin: 24px; } body { margin: 0; color: #15352a; font-family: DejaVu Sans, sans-serif; } .frame { height: 690px; padding: 42px 54px; border: 10px solid #075b3b; position: relative; } .bar { height: 7px; background: #d6aa2b; margin-bottom: 38px; } .authority { font-size: 13px; font-weight: bold; text-transform: uppercase; letter-spacing: 1px; } h1 { margin: 36px 0 8px; font-size: 34px; color: #075b3b; } .number { color: #65756e; font-size: 14px; } .statement { margin: 36px 0 12px; font-size: 15px; } .holder { margin: 0; font-size: 30px; } .details { width: 72%; margin-top: 34px; border-collapse: collapse; } .details td { padding: 12px 10px; border-bottom: 1px solid #ccd7d1; } .details td:first-child { width: 160px; color: #65756e; font-size: 11px; text-transform: uppercase; } .qr { position: absolute; right: 52px; bottom: 68px; width: 165px; text-align: center; } .qr img { width: 155px; height: 155px; } .qr p { margin: 6px 0 0; font-size: 9px; color: #65756e; } .footer { position: absolute; left: 54px; bottom: 54px; font-size: 10px; color: #65756e; }
</style></head><body><div class="frame"><div class="bar"></div><div class="authority">Ghana Investment Promotion Authority<br>Investment Opportunities Mapping Project</div><h1>{{ $certificate->type->name }}</h1><div class="number">Certificate no. {{ $certificate->certificate_number }}</div><p class="statement">This digitally signed certificate is issued to</p><h2 class="holder">{{ $certificate->holder_name_snapshot }}</h2><table class="details"><tr><td>Organization</td><td>{{ $certificate->organization_name_snapshot ?: 'Not specified' }}</td></tr><tr><td>Project</td><td>{{ $certificate->project_name_snapshot ?: 'Not linked' }}</td></tr><tr><td>District</td><td>{{ $certificate->district->name }}, {{ $certificate->district->region->name }}</td></tr><tr><td>Issued</td><td>{{ $certificate->issued_at->format('j F Y') }}</td></tr><tr><td>Expires</td><td>{{ $certificate->expires_at?->format('j F Y') ?? 'No fixed expiry' }}</td></tr></table><div class="qr"><img src="{{ $qrDataUri }}" alt=""><p>Scan for live registry status</p></div><div class="footer">Authenticity depends on the live result at:<br>{{ $verificationUrl }}<br>Signing key: {{ $certificate->signing_key_id }}</div></div></body></html>